library ieee;use ieee.std_logic_1164.all;entity tb_timer_periodic is end;architecture tb of tb_timer_periodic is signal clk:std_logic:='0';signal rst_n:std_logic:='0';signal tick:std_logic;begin clk<=not clk after 5 ns;dut:entity work.timer_periodic generic map(G_CLOCK_HZ=>1_000_000,G_PERIOD_US=>4)port map(clk_i=>clk,rst_ni=>rst_n,enable_i=>'1',tick_o=>tick);process begin wait for 12 ns;rst_n<='1';for i in 1 to 4 loop wait until rising_edge(clk);wait for 1 ns;end loop;assert tick='1' severity error;report "PASS" severity note;wait;end process;end;
